//! Receiving a signal: taking it off the queue, writing the frame onto the
//! guest's stack and pointing the CPU at the handler — and `rt_sigreturn`,
//! which reads the frame back. The other half of `kernel/signal.c`, which is
//! gone.
//!
//! This was the part of the family that waited for `struct task` to move,
//! because it reads and writes `struct cpu_state`. It no longer has to:
//! `cpu_state` is generated by bindgen like the rest of the task, and the two
//! `static inline` helpers it needed from `emu/arch/arm64/cpu.h` — packing the
//! condition flags into both places they are kept, and telling the host's
//! floating-point control register what the guest's says — are four lines each
//! and are here as [`set_nzcv`] and [`fp_sync_to_host`].
//!
//! # The lock is a guard, and the two paths that drop it say so
//!
//! Every step of a delivery runs under sighand's lock: the disposition is
//! read, the frame built, the mask changed and the one-shot handler reset under
//! one acquisition, so nothing can change the table between the decision and
//! its effect. Two paths give it up. A default action that kills the process
//! drops the guard before `do_exit_group`, which never returns; and a ptrace
//! stop drops it around the wait for the tracer and takes it back after. In C
//! both were an `unlock` in the middle of a function that had taken the lock
//! somewhere else, and the second was found the hard way: a delivery that could
//! not write the guest's stack called the version of `deliver_signal` that
//! takes the lock, from inside it.
//!
//! # A fault's frame is written before the CPU is changed
//!
//! The order is snapshot, encode, then registers, and the snapshot is taken
//! *after* the `SA_RESTART` rewind so that a handler which returns resumes at
//! the `svc` and not after it. What the frame carries as the alternate stack
//! and the blocked mask is the state before this delivery, which is what
//! `rt_sigreturn` has to put back.

use std::ffi::{CStr, c_int};

use kernel_pids::PidsGuard;
use kernel_sigdisp::{Action, Disposition, SIG_DFL};
use kernel_sigframe::{self as sigframe, FRAME_SIZE, INFO_OFFSET, Stack, UC_OFFSET};
use kernel_sighand::QueueGuard;
use kernel_sigqueue::{SigInfo, mask_of};
use strace::strace;
use usercopy::GuestMem;

use crate::{Target, current, deliver_signal, ffi, send_exit_signal};

#[path = "ptrace.rs"]
mod ptrace;
#[path = "regs.rs"]
mod regs;
use ptrace::signal_delivery_stop;
pub use ptrace::{ptrace_exec_event_stop, ptrace_exit_event_stop, ptrace_syscall_boundary};
use regs::{restore_regs, snapshot_regs};

use guest_errno::Errno;

/// `SIGINFO_NIL`: what a signal the kernel raises for its own reasons says
/// about its sender. `si_code` is `SI_KERNEL` and everything else is zero.
pub fn kernel_info() -> SigInfo {
    SigInfo {
        code: ffi::SI_KERNEL_ as c_int,
        ..SigInfo::default()
    }
}

/// What a parent's `SIGCHLD` says about a child that stopped or was trapped:
/// Linux's `do_notify_parent_cldstop`. `si_code` is `CLD_STOPPED` or
/// `CLD_TRAPPED`, `si_status` the signal that stopped it, `si_pid` the
/// *process* -- the leader's pid, not whichever thread stopped -- and
/// `si_uid` the child's real uid.
///
/// Both notifications sent `SI_KERNEL` with no pid until 2026-09-04, so a
/// handler installed with `SA_SIGINFO` could not tell which child had
/// stopped, while the exit notification and `waitid` both said. The exit
/// path fills the same struct in `crates/kernel/exitcalls`, and
/// `report_continued` in `crates/kernel/syscalldispatch` for a continue.
///
/// `si_utime` and `si_stime` are zero. Linux fills the thread's CPU times
/// there; nothing has been found reading them for a stop, and the continue
/// notification leaves them zero too. Recorded rather than silent.
///
/// Filled from handles under `pids_lock` since 2026-09-30. It read
/// `task->group->leader` through three raw dereferences, which a leaderless
/// group would have followed into null.
fn child_info(me: &kernel_pids::Task<'_>, leader: Option<kernel_pids::Task<'_>>, code: c_int, status: c_int) -> SigInfo {
    let mut info = SigInfo {
        sig: leader.map_or(0, |l| l.exit_signal()),
        code,
        ..SigInfo::default()
    };
    // The union's `child` arm, which is the one `code` names. A write to a
    // union field is safe; only a read is not.
    info.__bindgen_anon_1.child.pid = leader.map_or(0, |l| l.pid());
    info.__bindgen_anon_1.child.uid = me.uid();
    info.__bindgen_anon_1.child.status = status;
    info
}

/// Tell the calling task's parent that it stopped: `CLD_STOPPED` for a group
/// stop, `CLD_TRAPPED` for a ptrace one.
///
/// Takes `pids_lock`, which is what keeps the parent from being reaped
/// between the lookup and the use, so it runs after any sighand lock has been
/// given up -- the order everywhere is pids_lock then sighand's. It was two
/// copies of the same twelve lines until 2026-09-30, one per stop, each
/// making its handles from a raw task pointer.
pub(crate) fn notify_parent_of_stop(code: c_int, status: c_int) {
    let pids = PidsGuard::take();
    // Checked: a stopped task has a parent, but nothing here makes that true.
    let Some(me) = pids.me() else {
        return;
    };
    let Some(parent) = me.parent() else {
        return;
    };
    if let Some(g) = parent.group() {
        kernel_tgroup::tgroup_notify_child_exit(g);
    }
    let leader = me.group().and_then(|g| g.leader_task());
    let exit_signal = leader.map_or(0, |l| l.exit_signal());
    let info = child_info(&me, leader, code, status);
    send_exit_signal(parent, exit_signal, info);
}

// `sighand_of` and `stop_of` were here until 2026-10-16. Every caller was on
// the calling task, and the first read the task's `sighand` field without
// `pids_lock` -- a data race with the group-exit valve, which empties that
// field under the lock from another thread -- while `taskview` keeps this
// thread's own reference for exactly this reader. The second dereferenced
// `group` with no null check. Both are `with_current_queue` and
// `with_current_group` now.

use logline::printk;

// ---------------------------------------------------------------------------
// The CPU, as a frame sees it
// ---------------------------------------------------------------------------

// `set_nzcv` and `fp_sync_to_host` were written out here, and again in
// `crates/kernel/ptrace`, and a third time as a `static inline` in
// `emu/arch/arm64/cpu.h` that `kernel/task.c` wrapped for its Rust callers.
// They are `crates/kernel/taskview`'s `cpu` module since 2026-09-05; nothing
// compared the three.
// ---------------------------------------------------------------------------
// Delivering one
// ---------------------------------------------------------------------------

/// Where a handler returns to: `__kernel_rt_sigreturn` in the vdso. aarch64 has
/// no `sigreturn` syscall and the vdso carries only the `rt_` form, so a
/// handler without `SA_SIGINFO` returns the same way as one with it.
///
/// The calling task's: signal delivery runs on the thread it delivers to. It
/// took the task as a raw pointer until 2026-10-01 and read `mm` through it.
fn sigreturn_trampoline() -> u64 {
    const NAME: &CStr = c"__kernel_rt_sigreturn";
    let offset = kernel_vdso::vdso_symbol(NAME.to_bytes());
    if offset == 0 {
        // A build invariant: the vdso image is compiled into this binary.
        eprintln!("sigreturn not found in vdso, this should never happen");
        std::process::abort();
    }
    // Under the read lock `execve` writes it under. Delivery runs between
    // quanta, so this thread does not hold it already, and the frame write
    // above took it inside the same `sighand` lock.
    let vdso = pagetable::memlock::ReadGuard::current().map_or(0, |held| pagetable::memlock::Held::image(&held).vdso);
    vdso + offset as u64
}

#[path = "fatal.rs"]
mod fatal;
use fatal::terminate;

/// Deliver one dequeued signal to the calling thread.
///
/// Takes the guard and gives it back, so that the one path which cannot — the
/// default action that ends the process — is the one that does not return.
///
/// # Safety
/// Called on the guest thread `task` is, and `guard` holds its queue.
unsafe fn receive_signal<'a>(task: *mut ffi::task, mut guard: QueueGuard<'a>, info: &SigInfo) -> QueueGuard<'a> {
    let sig = info.sig;
    strace!(
        "{} receiving signal {}",
        taskview::current_pid(),
        sig
    );

    // The table and the rules are crates/kernel/sigdisp. It used to be a
    // switch here whose ignore set had five entries where Linux's has four.
    let action = guard.table().action(sig);
    // Linux's `get_signal`: init skips the default action of anything but
    // `SIGKILL` and `SIGSTOP`. One sent while it was blocked was not
    // discarded at generation, and arrives here.
    if matches!(action, Action::Stop | Action::Terminate)
        && crate::blockable(sig)
        && taskview::with_current_group(ffi::tgroup::unkillable) == Some(true)
    {
        return guard;
    }
    match action {
        Action::Ignore => return guard,
        Action::Stop => {
            // The flag and the status together, which is what a waiter reads
            // as one answer.
            taskview::with_current_group(|g| g.stop.stop(((sig << 8) | 0x7f) as u32));
            return guard;
        }
        Action::Terminate => {
            // do_exit_group must be called without this lock.
            drop(guard);
            unsafe { terminate(task, sig) }
        }
        Action::Handler => {}
    }

    let action: Disposition = guard.table().get(sig).unwrap_or_default();
    let flags = action.flags;
    let cpu = unsafe { (*task).cpu.get() };

    // SA_RESETHAND: a one-shot handler. Written back into the **table**, not
    // into the copy `get` filled -- which is what the line here used to do, so
    // the reset was thrown away with the copy and a SA_RESETHAND handler ran
    // every time. `head -1` on a program that handles the first ^C and dies on
    // the second never died. Found by signal_probe on its first run.
    //
    // Before the frame rather than after it, as Linux's `get_signal` does:
    // the reset is part of taking the signal off the queue, and applies
    // whether or not the handler can then be entered.
    if flags & ffi::SA_RESETHAND_ != 0 {
        guard.table_mut().set(
            sig,
            Disposition {
                handler: SIG_DFL,
                ..Disposition::default()
            },
        );
    }

    // SA_RESTART: if this handler asked for automatic restart and the syscall
    // being interrupted returned EINTR, rewind the pc to the `svc` and restore
    // the first argument, which the return value clobbered. The frame saved
    // next captures the rewound pc, so a handler that returns re-executes the
    // syscall instead of surfacing EINTR. Load-bearing for JSC's SIGPWR
    // GC-safepoint handshake, which registers SA_RESTART and otherwise
    // livelocks re-signalling a thread whose futex keeps returning EINTR.
    //
    // The pc the machine is actually at is what is passed in, and
    // crates/kernel/syscallrestart answers with the rewind or with nothing.
    // There is no flag to read: it used to be four fields and a comment saying
    // that reading the flag alone is unsafe. `handler_ran` is true here, which
    // is what makes an ERESTARTNOHAND syscall -- ppoll, pselect, rt_sigsuspend
    // -- refuse the rewind even with SA_RESTART: each replaced the signal mask
    // for its duration, and re-running one after a handler would wait under a
    // mask the guest has been told was restored.
    //
    // `restarts_regardless` is the fourth class, `ERESTARTNOINTR`: restarted
    // whether this handler asked or not (`FUTEX_LOCK_PI`).
    let asked = flags & ffi::SA_RESTART_ != 0
        || taskview::with_current_restart(|r| r.restarts_regardless()) == Some(true);
    if asked
        && let Some((pc, arg0)) =
            taskview::with_current_restart(|r| r.take_rewind(unsafe { (*cpu).pc }, true)).flatten()
    {
        // SAFETY: this thread's own CPU state; the JIT is not running.
        unsafe {
            (*cpu).pc = pc;
            (*cpu).regs[0] = arg0;
        }
    }

    // The frame, from the CPU as it is now and the alternate stack and mask
    // as they are now: what rt_sigreturn has to put back. `frame_used` is how
    // much of it carries anything -- the extension chain ends after the FPSIMD
    // record, and the reserved area past it is never read -- while sp moves by
    // the ABI's whole FRAME_SIZE.
    let mut frame = [0u8; FRAME_SIZE];
    // SAFETY: this thread's own registers, between guest instructions.
    let regs = snapshot_regs(unsafe { &*cpu });
    let sp_before = unsafe { (*cpu).sp };
    // The alternate stack is this thread's, from its queue: it was the
    // table's, one per process, and two Go threads in a handler at once wrote
    // their frames onto the same stack.
    let (alt_sp, alt_size, alt_flags) = guard.queue().altstack().report(sp_before);
    let stack = Stack {
        sp: alt_sp,
        flags: alt_flags as i32,
        size: alt_size,
    };
    let blocked_before = guard.queue().blocked();
    let frame_used = sigframe::encode(
        &mut frame,
        kernel_sigqueue::as_bytes(info),
        stack,
        blocked_before,
        &regs,
    );

    // Where the frame goes.
    let mut sp = sp_before;
    // Only switch to the alternate signal stack when the handler was
    // registered with SA_ONSTACK. This used to switch whenever an altstack
    // existed at all, which put EVERY handler on it. JSC's GC installs an
    // altstack for SIGSEGV but registers its SIGPWR thread-suspend handler
    // without SA_ONSTACK, and that handler compares the interrupted sp against
    // the thread's own stack bounds to decide whether to park: on the altstack
    // it bailed, the GC re-signalled for ever, and the claude-cli startup
    // deadlocked.
    let altstack = *guard.queue().altstack();
    if altstack.should_switch(flags, sp) {
        let (stack, size) = altstack.bounds();
        sp = stack + size;
    }
    sp -= FRAME_SIZE as u64;
    // ARM64 requires the stack to be 16-byte aligned.
    sp &= !0xf;

    // Install the frame -- only the part that carries something -- **before**
    // anything about the CPU or the mask changes. A stack that cannot take
    // the frame is an overflowed one, or an sp the program has pointed at
    // nothing, and Linux's `handle_signal` sets no register until
    // `setup_rt_frame` has succeeded. What stood here set sp, pc and the
    // handler's mask first and wrote the frame after, so on failure the guest
    // resumed *in the handler*, on the stack it had just failed to write,
    // with a SIGSEGV queued that the handler's own mask then blocked -- and
    // a stack overflow with a SIGSEGV handler did not die of SIGSEGV.
    if GuestMem::current().write(sp, &frame[..frame_used]) != 0 {
        printk(&format!("failed to install frame for {sig} at {sp:#x}"));
        // Recorded on the queue under the lock already held, rather than
        // through deliver_signal, which takes it: a non-recursive mutex, so
        // the thread stopped there for good. Reproduced by task_race once
        // enough signals were in flight to reach a guest stack that could not
        // be written; six threads ended up in __lock, one of them holding the
        // lock the other five wanted.
        force_sigsegv(&mut guard, sig);
        return guard;
    }

    // The mask while the handler runs. By default the signal itself is blocked,
    // which sigaction is allowed to customise.
    let mut blocked = blocked_before;
    if flags & ffi::SA_NODEFER_ == 0 {
        blocked |= mask_of(sig);
    }
    guard.queue_mut().set_blocked(blocked | action.mask);

    // The registers for the handler. An exception clears the exclusive
    // monitor.
    unsafe {
        (*cpu).excl_addr = u64::MAX;
        (*cpu).sp = sp;
        (*cpu).pc = action.handler;
        // ARM64 ABI: x0=signum, x1=siginfo*, x2=ucontext*. These are registers
        // rather than frame fields: the frame used to carry `pinfo` and `puc`
        // copies, which is what i386 does and which nothing ever read back.
        let regs = &mut (*cpu).regs;
        regs[0] = sig as u64;
        regs[1] = sp + INFO_OFFSET as u64;
        regs[2] = sp + UC_OFFSET as u64;
        // The guest returns through the vdso; the `restorer` the frame used to
        // carry was never read back either.
        regs[30] = sigreturn_trampoline();
    }
    guard
}

/// Linux's `force_sigsegv`, for a handler whose frame could not be written.
///
/// The process is not resumed where it was, and not in the handler either: it
/// gets a `SIGSEGV` it cannot decline. Two rules, both from `kernel/signal.c`:
///
/// - `force_sigsegv(sig)`: when the signal whose frame failed *is* `SIGSEGV`,
///   its disposition goes back to the default first, since a handler that
///   could not be entered once will not be entered for the fault it caused.
/// - `force_sig(SIGSEGV)`: a `SIGSEGV` that is blocked or ignored goes back to
///   the default and is unblocked, so the process cannot have arranged to
///   survive it. One that is *handled* and unblocked is queued like any other
///   -- a handler on an alternate stack runs, which is how a program that
///   installed one to report stack overflow gets to report it.
///
/// The `siginfo` is `SI_KERNEL`, which is what `SEND_SIG_PRIV` carries. The
/// signal is queued under the lock already held and taken off it by the same
/// delivery pass, because that pass re-reads the mask after every signal it
/// acts on.
///
/// Safe since 2026-09-30: its one obligation, that `q` was the queue under
/// `guard`, is what a [`QueueGuard`] is.
fn force_sigsegv(guard: &mut QueueGuard<'_>, sig: c_int) {
    let segv = ffi::SIGSEGV_ as c_int;
    if sig == segv {
        guard.table_mut().set(segv, Disposition::default());
    }
    let blocked = guard.queue().blocked() & mask_of(segv) != 0;
    let ignored = guard.table().action(segv) == Action::Ignore;
    if blocked || ignored {
        guard.table_mut().set(segv, Disposition::default());
        let queue = guard.queue_mut();
        let mask = queue.blocked();
        queue.set_blocked(mask & !mask_of(segv));
    }
    guard.queue_mut().arrive(segv, kernel_info(), true);
}

// ---------------------------------------------------------------------------
// The entry points
// ---------------------------------------------------------------------------

/// Take every deliverable signal off the calling thread's queue, one at a time.
///
/// Called by every interrupt on its way back to the guest, from
/// `crates/kernel/syscalldispatch`. Must be called without `pids_lock` or
/// sighand's lock held.
///
/// One at a time, taken off the queue as it is handled, rather than a list walk
/// holding the next entry: the ptrace stop *releases* sighand's lock and can
/// reach `do_exit_group`, so a pointer to the next node was being held across a
/// call that another thread could add to and that this thread might not come
/// back from.
///
pub fn receive_signals() {
    let task = current();
    // A thread the group-exit valve gave up on is `exiting`, and has nothing
    // to deliver to: it used to find its `sighand` field emptied here, and the
    // thread's own reference, which this reads now, outlives that.
    if task.is_null() || taskview::current_is_gone() {
        return;
    }
    let Some(was_stopped) = taskview::with_current_group(|g| g.stop.is_stopped()) else {
        return;
    };
    // SAFETY: `task` is the calling thread's, and `queue` is its own.
    let Some(retarget) = taskview::with_current_queue(|queue| unsafe { deliver_pending(task, queue) }) else {
        return;
    };
    if retarget != 0 {
        crate::routing::retarget_shared(retarget);
    }

    // A stop this delivery caused is reported to the parent from outside the
    // lock -- it needs pids_lock, and the order is pids_lock then sighand's.
    let stopped = taskview::with_current_group(|g| {
        // `CLD_STOPPED`, with the stopping signal as `si_status` -- which is
        // what waitid reports for the same stop, asked from the other side.
        (!was_stopped && g.stop.is_stopped())
            .then(|| g.stop.stop_signal().unwrap_or(ffi::SIGSTOP_) as c_int)
    });
    if let Some(stop_sig) = stopped.flatten() {
        notify_parent_of_stop(ffi::CLD_STOPPED_ as c_int, stop_sig);
    }
}

/// The body of [`receive_signals`], with the calling task's queue. Answers the
/// process-directed signals this thread has blocked since the last pass,
/// which another thread may have to take.
///
/// # Safety
/// `task` is the calling thread's task and `queue` its own.
unsafe fn deliver_pending(task: *mut ffi::task, queue: kernel_sighand::Queue<'_>) -> u64 {
    let mut guard = queue.lock();

    // A saved mask means the last system call was one like sigsuspend that
    // changes the mask for its duration. Only ignore a signal right now if it
    // was both blocked during the call and should still be blocked after it.
    let mut blocked = guard.queue().blocked();
    if let Some(saved) = guard.queue_mut().take_saved_mask() {
        blocked &= saved;
        guard.queue_mut().set_blocked(saved);
    }

    // The mask is read again after every signal acted on, because acting on
    // one changes it: entering a handler blocks the signal itself and
    // whatever `sa_mask` names. Read once before the loop -- which is what
    // stood here -- a second pending signal the first handler's mask blocks
    // was dequeued anyway and delivered *inside* that handler, which is
    // exactly what the mask was set to prevent. Linux delivers one signal per
    // pass and re-asks with the new mask; this asks the same question in one
    // pass. It is also what lets a `SIGSEGV` forced by a frame that could not
    // be written, and unblocked for the purpose, be taken in the same pass.
    //
    // The thread's own signals first and then its process's, which is Linux's
    // `dequeue_signal`; whether it looks at the process's at all is the
    // queue's to say (`Signals::take_next`).
    let mut allowed = !blocked;
    loop {
        let (own, shared) = guard.both_mut();
        let Some(info) = own.take_next(allowed, shared) else {
            break;
        };
        let traced = taskview::with_current_ptrace(|p| p.is_traced()) == Some(true);
        if traced && info.sig != ffi::SIGKILL_ as c_int {
            // Notifies the tracer, sleeps, and waits to be continued. Signals
            // that arrive meanwhile stay on the queue, except SIGKILL, which
            // ends the process from inside.
            guard = unsafe { signal_delivery_stop(task, queue, guard, info.sig, &info) };
        } else {
            guard = unsafe { receive_signal(task, guard, &info) };
        }
        allowed = !guard.queue().blocked();
    }
    let (own, shared) = guard.both_mut();
    own.recalc(shared)
}

/// `rt_sigreturn(2)`: put back what the frame on the guest's stack says.
///
/// Every byte of the frame is untrusted -- the guest may hand this whatever it
/// likes -- so the decoder answers `None` rather than trusting a length, and a
/// frame that cannot be read or parsed is a `SIGSEGV`.
///
/// Returns the **whole** restored `x0`: the dispatcher must not touch `x0`
/// after this, because the register state came from the frame.
///
/// Called on a guest thread, from the syscall table.
pub fn sys_rt_sigreturn() -> Result<i64, Errno> {
    let task = current();
    let cpu = unsafe { (*task).cpu.get() };
    // ARM64 keeps sp pointing at the start of the frame.
    let sp = unsafe { (*cpu).sp };

    let mut frame = [0u8; FRAME_SIZE];
    if GuestMem::current().read(sp, &mut frame) != 0 {
        deliver_signal(Target::Me, ffi::SIGSEGV_ as c_int, kernel_info());
        return Err(Errno::EFAULT);
    }
    let Some(decoded) = sigframe::decode(&frame) else {
        deliver_signal(Target::Me, ffi::SIGSEGV_ as c_int, kernel_info());
        return Err(Errno::EFAULT);
    };

    unsafe { restore_regs(cpu, &decoded.regs, decoded.have_fpsimd) };

    taskview::with_current_queue(|queue| {
        let mut guard = queue.lock();
        // The same setter sigaltstack uses, SS_DISABLE included, which the
        // duplicate that stood here silently ignored. The errors are the two
        // conditions it spelled out as an `if`, so dropping them is the same
        // behaviour.
        let _ = guard.queue_mut().altstack_mut().set(
            decoded.stack.sp,
            decoded.stack.size,
            decoded.stack.flags as u32,
            sp,
        );
        // The two unblockable signals are dropped without an error, which is
        // the other half of the rule sigdisp's may_change is the first half of.
        guard.queue_mut().set_blocked(kernel_sigdisp::maskable(decoded.sigmask));
    });
    // **The dispatcher discards this**, and has to: syscall 139 restores the
    // whole CPU from the signal frame, x0 included, so writing a return value
    // over it would corrupt what was restored. Both answers here are for a
    // reader rather than for the guest.
    Ok(unsafe { (*cpu).regs[0] as i64 })
}

#[cfg(test)]
#[path = "receive_tests.rs"]
mod tests;
